cat > "$B/port/TransportResult.kt" <<EOF
$H
package app.aware.core.protocol.port

/** One outcome of a request, classified per CORE-ERR-003. */
sealed class TransportResult<out T> {
    /** A success status with its decoded body. */
    data class Success<out T>(val value: T, val status: Int) : TransportResult<T>()

    /** Class R: failed request (network error, timeout, 5xx, other listed statuses). */
    data class Failed(val reason: String) : TransportResult<Nothing>()

    /** Class P: permanent rejection of a send (E3 only). [code] is null when the body has no valid error code. */
    data class Rejected(val status: Int, val code: String?) : TransportResult<Nothing>()
}
EOF

cat > "$B/port/Transport.kt" <<EOF
$H
package app.aware.core.protocol.port

import app.aware.core.protocol.wire.InfoResponse
import app.aware.core.protocol.wire.PollResponse
import app.aware.core.protocol.wire.SendRequest
import app.aware.core.protocol.wire.SendResponse
import app.aware.core.protocol.wire.SessionRequest
import app.aware.core.protocol.wire.SessionResponse
import app.aware.core.protocol.wire.UsersResponse

/** The five endpoints (PLAT-HOOK-009). Implementations never throw for HTTP or network outcomes. */
interface Transport {
    suspend fun info(): TransportResult<InfoResponse>

    suspend fun session(request: SessionRequest): TransportResult<SessionResponse>

    suspend fun send(epoch: String, request: SendRequest): TransportResult<SendResponse>

    /** [limit] null omits the parameter (server default POLL_LIMIT_MAX). */
    suspend fun poll(name: String, epoch: String, after: Long, limit: Int?): TransportResult<PollResponse>

    suspend fun users(): TransportResult<UsersResponse>
}
EOF

cat > "$B/port/LocalStore.kt" <<EOF
$H
package app.aware.core.protocol.port

import app.aware.core.protocol.store.SentMark
import app.aware.core.protocol.store.StoredMessage
import app.aware.core.protocol.store.StoredState

/**
 * Persistent client state (PLAT-HOOK-009): identity, epoch, cursor, messages and outbox.
 * Every write is atomic; [applyPoll] stores the envelopes and then the cursor in one transaction
 * (CORE-CURSOR-002), [resetEpoch] applies CORE-EPOCH-004 in one transaction.
 */
interface LocalStore {
    suspend fun read(): StoredState

    suspend fun saveIdentity(name: String)

    /** Stores a pending message with its enqueue order and records that order as the last assigned. */
    suspend fun insertPending(message: StoredMessage)

    suspend fun markSent(mark: SentMark)

    suspend fun deleteMessage(id: String)

    /** Deletes every message with a seq, sets the cursor to 0 and stores [epoch]. */
    suspend fun resetEpoch(epoch: String)

    suspend fun applyPoll(added: List<StoredMessage>, sent: List<SentMark>, cursor: Long)
}
EOF

cat > "$B/port/OutcomeClassifier.kt" <<EOF
$H
package app.aware.core.protocol.port

import app.aware.core.protocol.wire.WireJson
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive

/** Maps HTTP statuses to the classes of CORE-ERR-003. */
object OutcomeClassifier {
    val ERROR_CODES: Set<String> = setOf(
        "malformed_request",
        "invalid_name",
        "invalid_id",
        "invalid_type",
        "invalid_payload",
        "unknown_sender",
        "not_found",
        "method_not_allowed",
        "id_conflict",
        "epoch_mismatch",
        "payload_too_large",
        "unsupported_media_type",
        "internal_error",
    )

    /** E3 succeeds with 200 or 201 (CORE-MSG-001, CORE-DEDUPE-003); every other endpoint with 200. */
    fun isSuccess(endpoint: Endpoint, status: Int): Boolean =
        if (endpoint == Endpoint.SEND) status == 200 || status == 201 else status == 200

    /**
     * A non-success status. Class P only on E3 for 400 (any code), 409 id_conflict, 413 and 415;
     * everything else is class R (including 409 epoch_mismatch, CORE-EPOCH-005).
     */
    fun classify(endpoint: Endpoint, status: Int, code: String?): TransportResult<Nothing> {
        val validCode = code?.takeIf { it in ERROR_CODES }
        if (endpoint == Endpoint.SEND) {
            val permanent = status == 400 || status == 413 || status == 415 ||
                (status == 409 && validCode == "id_conflict")
            if (permanent) return TransportResult.Rejected(status, validCode)
        }
        return TransportResult.Failed(if (validCode == null) "http \$status" else "http \$status \$validCode")
    }

    /** The error code of an error body, or null when the body is not a valid error body. */
    fun errorCode(body: String?): String? {
        if (body.isNullOrEmpty()) return null
        val root = runCatching { WireJson.json.parseToJsonElement(body) }.getOrNull() as? JsonObject ?: return null
        val error = root["error"] as? JsonObject ?: return null
        val code = error["code"] as? JsonPrimitive ?: return null
        if (!code.isString) return null
        return code.content.takeIf { it in ERROR_CODES }
    }
}
EOF
